describe('Login Form Validation', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com/');
  });

  it('should display error messages when both username and password fields are empty', () => {
    cy.get('[data-test="login-button"]').click();
    cy.get('[data-testid="error"]').should('be.visible');
    cy.get('[data-testid="error"]').should('contain', 'Username is required');
    cy.get('[data-testid="error"]').should('contain', 'Password is required');
  });

  it('should display error message when only username is provided and password is empty', () => {
    cy.get('[data-test="username"]').type('standard_user');
    cy.get('[data-test="login-button"]').click();
    cy.get('[data-testid="error"]').should('be.visible');
    cy.get('[data-testid="error"]').should('contain', 'Password is required');
    cy.get('[data-testid="error"]').should('not.contain', 'Username is required');
  });
});
